-- Actual persisted review intake under rolled-back synthetic identities/terms, not actual commercial approval.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2060005-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('cancelled',true,'provider_confirmed',true,'effective_at',now()))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-lifecycle-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-005:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic subscriber'),(pg_temp.id(2),'Synthetic other subscriber');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic lifecycle practice'),(pg_temp.id(22),pg_temp.id(2),'Synthetic other practice');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(101),pg_temp.id(21),'Synthetic retained clinic','Etc/UTC');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(301),pg_temp.id(21),pg_temp.id(3),array['patients.read']);
insert into public.membership_locations(practice_id,membership_id,location_id)values(pg_temp.id(21),pg_temp.id(301),pg_temp.id(101));
set constraints all immediate;set constraints all deferred;
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
(pg_temp.id(51),'synthetic-m6-005',1,'approved','EGP',2,29900,7,4,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-lifecycle/v1','SYNTHETIC_NOT_COMMERCIAL_APPROVAL','SYNTHETIC_NOT_LEGAL_APPROVAL');
with moment as(select clock_timestamp()at time zone'UTC'as stamp)
insert into public.doctor_saas_periods(id,subscriber_user_id,terms_version_id,kind,started_at,ends_at,accepted_document_ref)
select pg_temp.id(61),pg_temp.id(1),pg_temp.id(51),'trial',(stamp-interval'1 day')at time zone'UTC',(stamp+interval'6 days')at time zone'UTC','synthetic-lifecycle/v1'from moment;
insert into public.doctor_saas_accounts(subscriber_user_id,current_period_id,state,reason_code)values(pg_temp.id(1),pg_temp.id(61),'enabled','trial_started');
update public.doctor_edition_policy set mode='administrative_candidate',revision=2,change_reason='Synthetic lifecycle request verification only';
create temporary table receipts(name text primary key,value jsonb);grant all on receipts to authenticated;
create temporary table originals as select ends_at from public.doctor_saas_periods where id=pg_temp.id(61);
create function pg_temp.request(action text,key integer,revision integer default 1,ack boolean default true)returns jsonb language sql security invoker as $$select public.doctor_request_saas_lifecycle(action,revision,pg_temp.id(61),pg_temp.id(51),'synthetic-lifecycle/v1',ack,pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select pg_temp.request('cancellation',71,1,false)$$,'22023','DOCTOR_LIFECYCLE_REQUEST_INVALID','explicit request acknowledgement is required');
select throws_ok($$select pg_temp.request('execute_cancellation',72)$$,'22023','DOCTOR_LIFECYCLE_REQUEST_INVALID','intake cannot execute cancellation');
select throws_ok($$select pg_temp.request('cancellation',73,2)$$,'40001','DOCTOR_LIFECYCLE_REQUEST_CONFLICT','invented revision cannot create request');
select throws_ok($$select public.doctor_request_saas_lifecycle('cancellation',1,pg_temp.id(62),pg_temp.id(51),'synthetic-lifecycle/v1',true,pg_temp.id(81))$$,'40001','DOCTOR_LIFECYCLE_REQUEST_CONFLICT','wrong original period cannot be acknowledged');
select throws_ok($$select public.doctor_request_saas_lifecycle('cancellation',1,pg_temp.id(61),pg_temp.id(52),'synthetic-lifecycle/v1',true,pg_temp.id(82))$$,'40001','DOCTOR_LIFECYCLE_REQUEST_CONFLICT','wrong terms version cannot be acknowledged');
select throws_ok($$select public.doctor_request_saas_lifecycle('cancellation',1,pg_temp.id(61),pg_temp.id(51),'synthetic-lifecycle/v2',true,pg_temp.id(83))$$,'40001','DOCTOR_LIFECYCLE_REQUEST_CONFLICT','wrong document reference cannot be acknowledged');
insert into receipts values('cancel',pg_temp.request('cancellation',74));
select is((select value->>'status'from receipts where name='cancel'),'requested','accepted request awaits review');
select is((select value->'effective_at'from receipts where name='cancel'),'null'::jsonb,'no effective cancellation date invented');
select is((select value->'provider_confirmation'from receipts where name='cancel'),'null'::jsonb,'acknowledgement is not provider confirmation');
select is((select value->>'entitlement_changed'from receipts where name='cancel'),'false','request cannot mutate entitlement');
select is((select value->>'charge_created'from receipts where name='cancel'),'false','request creates no renewal charge');
select is(pg_temp.request('cancellation',74),(select value from receipts where name='cancel'),'lost acknowledgement replays original receipt');
select is(pg_temp.request('cancellation',75),(select value from receipts where name='cancel'),'same current binding with new key creates no duplicate request');
select throws_ok($$select pg_temp.request('renewal',74)$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','same key cannot replace cancellation with renewal');
insert into receipts values('renew',pg_temp.request('renewal',76));
select is(public.doctor_saas_lifecycle_requests()->>'total','2','opposite requests retained separately without last-write-wins');
select is(public.doctor_saas_lifecycle_requests()->>'execution_available','false','list result cannot grant billing execution');
select is(public.doctor_saas_status()->>'state','trial','renewal/cancellation requests leave entitlement unchanged');
select pg_temp.claim(2);
select is(public.doctor_saas_lifecycle_requests()->>'total','0','foreign subscriber cannot read request history');
select throws_ok($$select pg_temp.request('cancellation',77)$$,'40001','DOCTOR_LIFECYCLE_REQUEST_CONFLICT','foreign period cannot become caller subscription');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.request('cancellation',78)$$,'42501',null,'independent secretary cannot request owner billing changes');
reset role;
select is((select count(*)::integer from public.doctor_saas_lifecycle_requests),2,'requests persist once per original binding/action');
select is((select current_period_id from public.doctor_saas_accounts where subscriber_user_id=pg_temp.id(1)),pg_temp.id(61),'requests do not replace period');
select is((select ends_at from public.doctor_saas_periods where id=pg_temp.id(61)),(select ends_at from originals),'original expiry preserved');
select is((select count(*)::integer from public.doctor_saas_periods),1,'requests create no periods');
select is((select count(*)::integer from public.doctor_saas_payment_intents),0,'renewal requests create no payment intent');
select throws_ok($$update public.doctor_saas_lifecycle_requests set action='reactivation'$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','request cannot be rewritten');
select throws_ok($$delete from public.doctor_saas_lifecycle_requests$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','request history cannot be erased');
select ok(not has_table_privilege('authenticated','public.doctor_saas_lifecycle_requests','SELECT'),'raw request data stays private');
select ok(not has_function_privilege('anon','public.doctor_request_saas_lifecycle(text,integer,uuid,uuid,text,boolean,uuid)','EXECUTE'),'anonymous requests denied');
select ok(not has_function_privilege('service_role','public.doctor_request_saas_lifecycle(text,integer,uuid,uuid,text,boolean,uuid)','EXECUTE'),'service metadata facade cannot bypass fresh user');
update public.doctor_saas_accounts set state='suspended',reason_code='operator_hold',revision=2 where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.request('cancellation',74),(select value from receipts where name='cancel'),'old accepted receipt remains historical after revision change');
select is(public.doctor_saas_status()->>'state','suspended','historical receipt cannot undo operator hold');
select throws_ok($$select pg_temp.request('reactivation',79)$$,'40001','DOCTOR_LIFECYCLE_REQUEST_CONFLICT','fresh stale request requires current binding');
select is(pg_temp.request('reactivation',80,2)->>'observed_state','suspended','new request records hold without bypass');
select is(public.doctor_saas_status()->>'state','suspended','reactivation request cannot execute reactivation');
reset role;
select is((select count(*)::integer from public.locations where id=pg_temp.id(101)),1,'billing requests retain practice records');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key in(pg_temp.id(71),pg_temp.id(72),pg_temp.id(73),pg_temp.id(77),pg_temp.id(78),pg_temp.id(79),pg_temp.id(81),pg_temp.id(82),pg_temp.id(83))),'denied commands create no success receipt');
select * from finish();rollback;
